}

def dijkstra(start):
    dist = {v: float("inf") for v in graph}
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, v = heapq.heappop(pq)
        if d > dist[v]:
            continue
        for w, cost in graph[v]:
            if d + cost < dist[w]:
                dist[w] = d + cost
                heapq.heappush(pq, (dist[w], w))
    return dist

