class MinTree:
    def __init__(self, a):
        self.n = len(a)
        self.t = [float("inf")] * (2 * self.n)
        self.t[self.n:] = a
        for i in range(self.n - 1, 0, -1):
            self.t[i] = min(self.t[2 * i], self.t[2 * i + 1])
    def update(self, i, v):
        i += self.n
        self.t[i] = v
        while i > 1:
            i //= 2
            self.t[i] = min(self.t[2 * i], self.t[2 * i + 1])
    def query(self, l, r):
        s = float("inf")
        l += self.n; r += self.n
        while l < r:
            if l & 1: s = min(s, self.t[l]); l += 1
            if r & 1: r -= 1; s = min(s, self.t[r])
            l //= 2; r //= 2
        return s

