def make_pi(p):
    pi = [0] * len(p)
    j = 0
    for i in range(1, len(p)):
        while j > 0 and p[i] != p[j]:
            j = pi[j - 1]
        if p[i] == p[j]:
            j += 1
            pi[i] = j
    return pi

def kmp(text, p):
    pi, j, found = make_pi(p), 0, []
    for i, ch in enumerate(text):
        while j > 0 and ch != p[j]:
            j = pi[j - 1]
        if ch == p[j]:
            if j == len(p) - 1:
                found.append(i - j)
                j = pi[j]
            else:
                j += 1
    return found

