  function term() {
    let v = power();
    while (peek() === "*" || peek() === "/") v = next() === "*" ? v * power() : v / power();
    return v;
  }
  function power() {
    const b = factor();
    if (peek() === "^") { next(); return b ** power(); }
    return b;
  }
  function factor() {
    const t = next();
    if (t === "-") return -factor();
